const STORAGE_KEY = "inkflow:vocabulary-book:v1";

function relativeDate(days: number, hours = 9): string {
  const date = new Date();
  date.setDate(date.getDate() + days);
  date.setHours(hours, 0, 0, 0);
  return date.toISOString();
}

function seedWord(
  word: Omit<
    VocabularyWord,
    | "id"
    | "addedAt"
    | "reviewStage"
    | "reviewCount"
    | "correctStreak"
    | "lapses"
    | "nextReviewAt"
    | "mastery"
  > &
    Partial<
      Pick<
        VocabularyWord,
        | "id"
        | "addedAt"
        | "reviewStage"
        | "reviewCount"
        | "correctStreak"
        | "lapses"
        | "nextReviewAt"
        | "mastery"
      >
    >,
): VocabularyWord {
  const reviewStage = word.reviewStage ?? 0;
  const reviewCount = word.reviewCount ?? 0;
  return {
    id: word.id ?? `word-${createId()}`,
    addedAt: word.addedAt ?? relativeDate(-14),
    reviewStage,
    reviewCount,
    correctStreak: word.correctStreak ?? Math.min(reviewCount, 3),
    lapses: word.lapses ?? 0,
    nextReviewAt: word.nextReviewAt ?? relativeDate(0),
    mastery: word.mastery ?? masteryFor(reviewStage, reviewCount),
    ...word,
  };
}

