export const DEFAULT_VOCABULARY_BOOK: VocabularyBook = {
  id: "my-oxford-wordbook",
  name: "我的牛津词汇书",
  subtitle: "Leafia · Ebbinghaus Edition",
  description: "从阅读、词典查询和语料库中收集的英语表达。",
  theme: "oxford",
  accent: COVER_THEMES[0]!.accent,
  createdAt: relativeDate(-28),
  updatedAt: new Date().toISOString(),
};

function masteryFor(stage: number, reviewCount: number): VocabularyMastery {
  if (reviewCount === 0) return "new";
  if (stage >= 5 && reviewCount >= 6) return "mastered";
  if (reviewCount >= 2) return "review";
  return "learning";
}

function normalizeTerm(term: string) {
  return term.trim().toLowerCase().replace(/\s+/g, " ");
}

function nextDateForStage(stage: number) {
  const days =
    REVIEW_INTERVALS_DAYS[Math.min(stage, REVIEW_INTERVALS_DAYS.length - 1)] ??
    30;
  return relativeDate(Math.max(0, days), 9);
}

function insightToWord(
  insight: LanguageInsight,
  sourceLabel: string,
  sourceExcerpt?: string,
  metadata?: Pick<
    VocabularyWord,
    "categoryId" | "bookId" | "moduleId" | "nodeId"
  >,
): VocabularyWord {
  return {
    id: `word-${createId()}`,
    term: insight.term,
    lemma: insight.lemma || insight.term,
    pronunciation: insight.pronunciation,
    partOfSpeech: insight.partOfSpeech,
    cefr: insight.cefr,
    meaningsZh: insight.meaningsZh,
    definitionEn: insight.definitionEn,
    collocations: insight.collocations,
    examples: insight.examples,
    usageNotes: insight.usageNotes,
    sourceLabel,
    sourceExcerpt,
    ...metadata,
    addedAt: new Date().toISOString(),
    reviewStage: 0,
    reviewCount: 0,
    correctStreak: 0,
    lapses: 0,
    nextReviewAt: new Date().toISOString(),
    mastery: "new",
  };
}

async function persist(book: VocabularyBook, words: VocabularyWord[]) {
  if (typeof indexedDB === "undefined") return;
  await idbSet(STORAGE_KEY, { book, words }).catch(() => undefined);
}

function applyRating(
  word: VocabularyWord,
  rating: ReviewRating,
): VocabularyWord {
  const now = new Date().toISOString();
  let stage = word.reviewStage;
  let reviewCount = word.reviewCount + 1;
  let correctStreak = word.correctStreak;
  let lapses = word.lapses;

  if (rating === "again") {
    stage = Math.max(0, stage - 2);
    correctStreak = 0;
    lapses += 1;
  } else if (rating === "hard") {
    stage = Math.max(0, stage);
    correctStreak = Math.max(0, correctStreak - 1);
  } else if (rating === "good") {
    stage = Math.min(REVIEW_INTERVALS_DAYS.length - 1, stage + 1);
    correctStreak += 1;
  } else {
    stage = Math.min(REVIEW_INTERVALS_DAYS.length - 1, stage + 2);
    correctStreak += 1;
  }

  // InkFlow requires at least two meaningful interactions before a word can
  // graduate into a longer interval.
  if (reviewCount < 2) {
    stage = Math.min(stage, 1);
  }

  return {
    ...word,
    reviewStage: stage,
    reviewCount,
    correctStreak,
    lapses,
    lastReviewedAt: now,
    nextReviewAt:
      rating === "again"
        ? relativeDate(0, new Date().getHours() + 1)
        : nextDateForStage(stage),
    mastery: masteryFor(stage, reviewCount),
  };
}

export const useVocabulary = create<VocabularyState>((set, get) => ({
  initialized: false,
  book: DEFAULT_VOCABULARY_BOOK,
  words: createSeedWords(),
  reviewMode: "flashcard",
  reviewDirection: "english-chinese",
  session: null,

  async hydrate() {
    if (get().initialized) return;
    const stored = await idbGet<PersistedVocabulary>(STORAGE_KEY).catch(
      () => undefined,
    );
    if (stored?.book && Array.isArray(stored.words)) {
      set({
        book: {
          ...DEFAULT_VOCABULARY_BOOK,
          ...stored.book,
        },
        words: stored.words,
        initialized: true,
      });
      return;
    }
    const book = { ...DEFAULT_VOCABULARY_BOOK, updatedAt: new Date().toISOString() };
    const words = createSeedWords();
    set({ book, words, initialized: true });
    await persist(book, words);
  },

  updateBook(patch) {
    const book = {
      ...get().book,
      ...patch,
      updatedAt: new Date().toISOString(),
    };
    set({ book });
    void persist(book, get().words);
  },

  addInsight(
    insight,
    sourceLabel = "Dictionary",
    sourceExcerpt,
    metadata,
  ) {
    const normalized = normalizeTerm(insight.term);
    if (!normalized) return;
    const existing = get().words.find(
      (word) => normalizeTerm(word.term) === normalized,
    );
    if (existing) {
      const words = get().words.map((word) =>
        word.id === existing.id
          ? {
              ...word,
              meaningsZh: insight.meaningsZh,
              definitionEn: insight.definitionEn,
              collocations: insight.collocations,
              examples: insight.examples,
              usageNotes: insight.usageNotes,
              ...metadata,
            }
          : word,
      );
      set({ words });
      void persist(get().book, words);
      return;
    }

    const words = [
      insightToWord(insight, sourceLabel, sourceExcerpt, metadata),
      ...get().words,
    ];
    set({ words });
    void persist(get().book, words);
  },

  addManyInsights(
    insights,
    sourceLabel = "Imported document",
    sourceExcerpt,
    metadata,
  ) {
    const existing = new Set(
      get().words.map((word) => normalizeTerm(word.term)),
    );
    const additions: VocabularyWord[] = [];
    for (const insight of insights) {
      const normalized = normalizeTerm(insight.term);
      if (!normalized || existing.has(normalized)) continue;
      existing.add(normalized);
      additions.push(
        insightToWord(insight, sourceLabel, sourceExcerpt, metadata),
      );
    }
    if (additions.length === 0) return 0;
    const words = [...additions, ...get().words];
    set({ words });
    void persist(get().book, words);
    return additions.length;
  },

  addCorpusEntry(entry) {
    get().addInsight(
      {
        term: entry.term,
        lemma: entry.normalizedTerm,
        meaningsZh: entry.meaningsZh,
        definitionEn: entry.definitionEn,
        collocations: entry.collocations,
        examples: [],
        usageNotes: [],
        provider: "mock",
      },
      entry.sourceLabel,
    );
  },

  removeWord(id) {
    const words = get().words.filter((word) => word.id !== id);
    set({ words });
    void persist(get().book, words);
  },

  setReviewMode(mode) {
    set({ reviewMode: mode });
  },

  setReviewDirection(direction) {
    set({ reviewDirection: direction });
  },

  startReview() {
    const now = Date.now();
    const due = get().words.filter(
      (word) => new Date(word.nextReviewAt).getTime() <= now,
    );
    const queue = (due.length > 0 ? due : get().words).slice(0, 12);
    if (queue.length === 0) return;
    set({
      session: {
        wordIds: queue.map((word) => word.id),
        roundWordIds: queue.map((word) => word.id),
        retryQueue: [],
        index: 0,
        round: 1,
        completed: false,
        ratings: {},
      },
    });
  },

  startReviewWithIds(ids) {
    const known = new Set(get().words.map((word) => word.id));
    const queue = [...new Set(ids)].filter((id) => known.has(id));
    if (queue.length === 0) return;
    set({
      session: {
        wordIds: queue,
        roundWordIds: queue,
        retryQueue: [],
        index: 0,
        round: 1,
        completed: false,
        ratings: {},
      },
    });
  },

  gradeCurrentWord(rating) {
    const session = get().session;
    if (!session || session.completed) return;
    const wordId = session.wordIds[session.index];
    if (!wordId) return;

    const passed = rating === "good" || rating === "easy";
    const shouldPersistRating = !passed || session.round === 2;
    const words = shouldPersistRating
      ? get().words.map((word) =>
          word.id === wordId ? applyRating(word, rating) : word,
        )
      : get().words;
    const ratings = {
      ...session.ratings,
      [wordId]: [...(session.ratings[wordId] ?? []), rating],
    };
    const retryQueue = passed
      ? session.retryQueue
      : [...session.retryQueue, wordId];
    const nextIndex = session.index + 1;
    let nextSession: ReviewSession = {
      ...session,
      ratings,
      retryQueue,
      index: nextIndex,
    };

    if (nextIndex >= session.wordIds.length) {
      if (retryQueue.length > 0) {
        nextSession = {
          ...nextSession,
          wordIds: retryQueue,
          retryQueue: [],
          index: 0,
        };
      } else if (session.round === 1) {
        nextSession = {
          ...nextSession,
          wordIds: session.roundWordIds,
          index: 0,
          round: 2,
        };
      } else {
        nextSession = {
          ...nextSession,
          completed: true,
        };
      }
    }

    set({ words, session: nextSession });
    void persist(get().book, words);
  },

  closeReview() {
    set({ session: null });
  },
}));

export function dueVocabularyWords(words: VocabularyWord[], now = Date.now()) {
  return words.filter((word) => new Date(word.nextReviewAt).getTime() <= now);
}

export function vocabularyMasteryCounts(words: VocabularyWord[]) {
  return {
    new: words.filter((word) => word.mastery === "new").length,
    learning: words.filter((word) => word.mastery === "learning").length,
    review: words.filter((word) => word.mastery === "review").length,
    mastered: words.filter((word) => word.mastery === "mastered").length,
  };
}

export function stageLabel(word: VocabularyWord) {
  if (word.mastery === "new") return "尚未开始";
  return `第 ${Math.min(word.reviewStage + 1, REVIEW_INTERVALS_DAYS.length)}/${REVIEW_INTERVALS_DAYS.length} 轮`;
}
